from sqlalchemy import String, text
from sqlalchemy.orm import DeclarativeBase, mapped_column


class Base(DeclarativeBase):
    pass


def hash_id(sequence: str):
    """TEXT primary key generated by the database via md5 hash of a sequence value."""
    return mapped_column(
        String(32),
        primary_key=True,
        server_default=text(f"md5(nextval('{sequence}')::text)"),
    )
